export class ApiError extends Error {
  constructor(
    public code: string,
    message: string,
    public status: number,
    public fields?: { field: string; code: string }[],
    public requestId?: string,
  ) {
    super(message);
  }
}

export function randomKey(): string {
  // getRandomValues also works on local HTTP hostnames used by container previews.
  // These keys identify retries/items; authentication credentials are generated by the API.
  return Array.from(crypto.getRandomValues(new Uint8Array(16)), (value) =>
    value.toString(16).padStart(2, "0"),
  ).join("");
}
let refreshing: Promise<boolean> | null = null;
function csrf() {
  return (
    document.cookie
      .split("; ")
      .find((c) => c.startsWith("nour_csrf="))
      ?.split("=")
      .slice(1)
      .join("=") || ""
  );
}
function headers(init?: RequestInit) {
  const result = new Headers(init?.headers);
  result.set("Accept-Language", document.documentElement.lang || "en");
  if (init?.body) result.set("Content-Type", "application/json");
  if (!["GET", "HEAD"].includes(init?.method || "GET"))
    result.set("X-CSRF-Token", decodeURIComponent(csrf()));
  return result;
}
export async function api<T>(
  path: string,
  init?: RequestInit,
  retry = true,
): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`/api/v1${path}`, {
      ...init,
      headers: headers(init),
      credentials: "include",
      cache: "no-store",
    });
  } catch (error) {
    if ((error as Error).name === "AbortError") throw error;
    throw new ApiError("network", "Connection unavailable", 0);
  }
  if (
    response.status === 401 &&
    retry &&
    !["/auth/login", "/auth/register", "/auth/refresh"].includes(path) &&
    csrf()
  ) {
    if (!refreshing)
      refreshing = api("/auth/refresh", { method: "POST" }, false)
        .then(() => true)
        .catch(() => false)
        .finally(() => {
          refreshing = null;
        });
    if (await refreshing) return api<T>(path, init, false);
    window.dispatchEvent(new Event("nour:expired"));
  }
  if (!response.ok) {
    const body = await response.json().catch(() => ({}));
    throw new ApiError(
      body.error?.code || "internal",
      body.error?.message || "Request failed",
      response.status,
      body.error?.fields,
      body.error?.request_id,
    );
  }
  return response.status === 204 ? (undefined as T) : response.json();
}
export function normalizeNumber(value: string): string {
  return value
    .replace(/[٠-٩]/g, (c) => String(c.charCodeAt(0) - 1632))
    .replace(/[۰-۹]/g, (c) => String(c.charCodeAt(0) - 1776))
    .replace(/٫/g, ".")
    .replace(/٬/g, "")
    .trim();
}
export function localDay(zone: string, value = new Date()) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: zone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(value);
  const get = (type: string) => parts.find((p) => p.type === type)?.value;
  return `${get("year")}-${get("month")}-${get("day")}`;
}
export function zonedDateTime(day: string, clock: string, zone: string) {
  const [y, m, d] = day.split("-").map(Number);
  const [hour, minute] = clock.split(":").map(Number);
  const guess = Date.UTC(y, m - 1, d, hour, minute);
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: zone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(new Date(guess));
  const n = (type: string) => Number(parts.find((p) => p.type === type)?.value);
  const shown = Date.UTC(
    n("year"),
    n("month") - 1,
    n("day"),
    n("hour"),
    n("minute"),
    n("second"),
  );
  return new Date(guess + (guess - shown)).toISOString();
}
